  | "pending"
  | "suspended"
  | "in_progress"
  | "delivered"
  | "discarded"
  | "failed";

export interface AgentSteeringCompletion {
  id: string;
  requesterSessionKey: string;
  result: unknown;
  prompt?: string;
  status: AgentSteeringCompletionStatus;
  steeringLeaseId?: string;
  steeringLeaseExpiresAt?: string;
  createdAt: string;
  updatedAt: string;
}

export interface EnqueueAgentSteeringCompletionInput {
  id?: string;
  completionId?: string;
  requesterSessionKey: string;
  result?: unknown;
  prompt?: string;
  status?: "pending" | "suspended";
  createdAt?: string | Date;
}

export interface LeaseAgentSteeringCompletionInput {
  requesterSessionKey: string;
  completionId?: string;
  now?: string | Date;
}

export interface AgentSteeringLease {
  completion: AgentSteeringCompletion;
  completionId: string;
  requesterSessionKey: string;
  steeringLeaseId: string;
  leaseExpiresAt: string;
  prompt: string;
  mergedPrompt: string;
  result: unknown;
}

export interface AcknowledgeAgentSteeringCompletionInput {
  requesterSessionKey: string;
  completionId: string;
  steeringLeaseId: string;
  now?: string | Date;
}

export interface ReleaseAgentSteeringCompletionInput {
  requesterSessionKey: string;
  completionId: string;
  steeringLeaseId: string;
  now?: string | Date;
  reason?: string;
}

export interface CancelAgentSteeringCompletionInput {
  requesterSessionKey: string;
  completionId: string;
  status?: "discarded" | "failed";
  now?: string | Date;
}

const LEASE_DURATION_MS = 5 * 60 * 1_000;
const TERMINAL_STATUSES = new Set<AgentSteeringCompletionStatus>([
  "delivered",
  "discarded",
  "failed",
]);

function dateValue(value: string | Date | undefined): Date {
  if (value instanceof Date) return new Date(value.getTime());
  if (typeof value === "string") return new Date(value);
  return new Date();
}

function iso(value: string | Date | undefined): string {
  return dateValue(value).toISOString();
}

function stringifyResult(result: unknown): string {
  if (typeof result === "string") return result;
  if (result === undefined) return "";
  try {
    return JSON.stringify(result) ?? "";
  } catch {
    return String(result);
  }
}

function mergePrompt(completion: Pick<AgentSteeringCompletion, "prompt" | "result">): string {
  const result = stringifyResult(completion.result);
  const prompt = completion.prompt?.trim() ?? "";
  if (!prompt) return result;
  if (!result) return prompt;
  return `${prompt}\n\n${result}`;
}

function cloneCompletion(completion: AgentSteeringCompletion): AgentSteeringCompletion {
  return { ...completion };
}

/**
 * An in-memory, requester-isolated steering completion queue.
 *
 * Lease ownership is represented by both the lease id and the requesting session.
 * Consequently an acknowledgement cannot acknowledge another session's lease, and an
 * acknowledgement from an old lease cannot acknowledge a completion after it has
 * been released or leased again.
 */
export class AgentSteeringQueue {
  private readonly completions = new Map<string, AgentSteeringCompletion>();

  enqueue(input: EnqueueAgentSteeringCompletionInput): AgentSteeringCompletion {
    const id = input.id ?? input.completionId ?? randomUUID();
    const now = iso(input.createdAt);
    const existing = this.completions.get(id);
    if (existing && !TERMINAL_STATUSES.has(existing.status)) {
      existing.requesterSessionKey = input.requesterSessionKey;
      existing.result = input.result;
      existing.prompt = input.prompt;
      existing.status = input.status ?? "pending";
      existing.updatedAt = now;
      existing.steeringLeaseId = undefined;
      existing.steeringLeaseExpiresAt = undefined;
      return cloneCompletion(existing);
    }

    const completion: AgentSteeringCompletion = {
      id,
      requesterSessionKey: input.requesterSessionKey,
      result: input.result,
      prompt: input.prompt,
      status: input.status ?? "pending",
      createdAt: now,
      updatedAt: now,
    };
    this.completions.set(id, completion);
    return cloneCompletion(completion);
  }

  listPending(requesterSessionKey: string): AgentSteeringCompletion[] {
    return [...this.completions.values()]
      .filter(
        (completion) =>
          completion.requesterSessionKey === requesterSessionKey &&
          (completion.status === "pending" || completion.status === "suspended"),
      )
      .map(cloneCompletion);
  }

  lease(input: LeaseAgentSteeringCompletionInput): AgentSteeringLease | null {
    const now = dateValue(input.now);
    const candidates = [...this.completions.values()]
      .filter((completion) => {
        if (completion.requesterSessionKey !== input.requesterSessionKey) return false;
        if (completion.status === "pending" || completion.status === "suspended") return true;
        if (completion.status !== "in_progress") return false;
        const expiry = completion.steeringLeaseExpiresAt
          ? dateValue(completion.steeringLeaseExpiresAt)
          : undefined;
        return expiry === undefined || now.getTime() - expiry.getTime() > LEASE_DURATION_MS;
      })
      .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.id.localeCompare(b.id));

    const completion = input.completionId
      ? candidates.find((candidate) => candidate.id === input.completionId)
      : candidates[0];
    if (!completion) return null;

    const steeringLeaseId = randomUUID();
    const leaseExpiresAt = new Date(now.getTime() + LEASE_DURATION_MS).toISOString();
    completion.status = "in_progress";
    completion.steeringLeaseId = steeringLeaseId;
    completion.steeringLeaseExpiresAt = leaseExpiresAt;
    completion.updatedAt = now.toISOString();

    const prompt = mergePrompt(completion);
    return {
      completion: cloneCompletion(completion),
      completionId: completion.id,
      requesterSessionKey: completion.requesterSessionKey,
      steeringLeaseId,
      leaseExpiresAt,
      prompt,
      mergedPrompt: prompt,
      result: completion.result,
    };
  }

  acknowledge(input: AcknowledgeAgentSteeringCompletionInput): boolean {
    const completion = this.completions.get(input.completionId);
    if (!completion) return false;
    if (completion.requesterSessionKey !== input.requesterSessionKey) return false;
    if (completion.status !== "in_progress") return false;
    if (!completion.steeringLeaseId) return false;
    if (completion.steeringLeaseId !== input.steeringLeaseId) return false;

    completion.status = "delivered";
    completion.updatedAt = iso(input.now);
    completion.steeringLeaseId = undefined;
    completion.steeringLeaseExpiresAt = undefined;
    return true;
  }

  release(input: ReleaseAgentSteeringCompletionInput): boolean {
    const completion = this.completions.get(input.completionId);
    if (!completion) return false;
    if (completion.requesterSessionKey !== input.requesterSessionKey) return false;
    if (completion.status !== "in_progress") return false;
    if (!completion.steeringLeaseId) return false;
    if (completion.steeringLeaseId !== input.steeringLeaseId) return false;

    completion.status = "pending";
    completion.updatedAt = iso(input.now);
    completion.steeringLeaseId = undefined;
    completion.steeringLeaseExpiresAt = undefined;
    return true;
  }

  cancel(input: CancelAgentSteeringCompletionInput): boolean {
    const completion = this.completions.get(input.completionId);
    if (!completion) return false;
    if (completion.requesterSessionKey !== input.requesterSessionKey) return false;
    if (TERMINAL_STATUSES.has(completion.status)) return false;

    completion.status = input.status ?? "discarded";
    completion.updatedAt = iso(input.now);
    completion.steeringLeaseId = undefined;
    completion.steeringLeaseExpiresAt = undefined;
    return true;
  }

  get(completionId: string): AgentSteeringCompletion | undefined {
    const completion = this.completions.get(completionId);
    return completion ? cloneCompletion(completion) : undefined;
  }
}

export const agentSteeringQueue = new AgentSteeringQueue();

export function enqueueAgentSteeringCompletion(
  input: EnqueueAgentSteeringCompletionInput,
): AgentSteeringCompletion {
  return agentSteeringQueue.enqueue(input);
}

export function listPendingAgentSteeringCompletions(
  requesterSessionKey: string,
): AgentSteeringCompletion[] {
  return agentSteeringQueue.listPending(requesterSessionKey);
}

export function leaseAgentSteeringCompletion(
  input: LeaseAgentSteeringCompletionInput,
): AgentSteeringLease | null {
  return agentSteeringQueue.lease(input);
}

export function acknowledgeAgentSteeringCompletion(
  input: AcknowledgeAgentSteeringCompletionInput,
): boolean {
  return agentSteeringQueue.acknowledge(input);
}

export function releaseAgentSteeringCompletion(
  input: ReleaseAgentSteeringCompletionInput,
): boolean {
  return agentSteeringQueue.release(input);
}

export function cancelAgentSteeringCompletion(
  input: CancelAgentSteeringCompletionInput,
): boolean {
  return agentSteeringQueue.cancel(input);
}

// Short aliases retained for callers that use the steering terminology directly.
export const enqueueSteeringCompletion = enqueueAgentSteeringCompletion;
export const leaseSteeringCompletion = leaseAgentSteeringCompletion;
export const ackSteeringCompletion = acknowledgeAgentSteeringCompletion;
export const acknowledgeSteeringCompletion = acknowledgeAgentSteeringCompletion;
export const releaseSteeringCompletion = releaseAgentSteeringCompletion;
export const cancelSteeringCompletion = cancelAgentSteeringCompletion;
